// ============================================================
// Node 1: PREPARE SEARCH QUERY
// Extract question, detect language, validate input
// ============================================================
const body = $input.item.json.body || $input.item.json;
const question = (body.question || body.query || body.message || '').trim();
const lang = (body.lang || 'fr').toLowerCase();

if (!question || question.length < 2) {
  return {
    json: {
      error: true,
      status: 'VALIDATION_ERROR',
      answer: lang === 'fr'
        ? 'Veuillez poser une question (champ "question" requis, minimum 2 caracteres).'
        : 'Please provide a question (field "question" required, minimum 2 characters).',
      sources: [],
      confidence: 0.0,
      engine: 'PROJECT_CHATBOT_V3',
      timestamp: new Date().toISOString()
    }
  };
}

// Detect topic category for Supabase query targeting
const topicKeywords = {
  financial: /revenue|chiffre|bilan|balance|financ|sales|vente|profit|cost|margin|quarterly|annuel/i,
  pipeline: /pipeline|standard|graph|quantit|orchestrat|rag|accuracy|precis|phase/i,
  infrastructure: /infra|server|vm|cloud|hf space|vercel|codespace|database|pinecone|neo4j|supabase/i,
  sector: /btp|construction|industri|financ|juridique|legal|secteur|sector/i,
  pme: /pme|sme|connecteur|connector|slack|gmail|whatsapp|telegram|multi-canal/i
};

let detectedTopic = 'general';
for (const [topic, regex] of Object.entries(topicKeywords)) {
  if (regex.test(question)) {
    detectedTopic = topic;
    break;
  }
}

return {
  json: {
    error: false,
    question: question,
    lang: lang,
    detectedTopic: detectedTopic,
    timestamp: new Date().toISOString()
  }
};

