// ============================================================
// Node 5: FORMAT CONTEXT FROM PINECONE + SUPABASE
// Merge retrieval results into a structured context for the LLM
// ============================================================

const prepareNode = $node['Prepare Search Query'].json;
const question = prepareNode.question;
const lang = prepareNode.lang;
const detectedTopic = prepareNode.detectedTopic;

// --- Extract Pinecone results ---
let pineconeContext = '';
let pineconeSourceIds = [];
let pineconeScores = [];

try {
  const pineconeData = $node['Search Pinecone'].json;
  const matches = pineconeData.matches || [];

  if (matches.length > 0) {
    const relevantMatches = matches.filter(m => (m.score || 0) >= 0.3);

    pineconeContext = relevantMatches.map((m, i) => {
      const meta = m.metadata || {};
      const text = meta.text || meta.content || meta.chunk_text || meta.document_text || '';
      const source = meta.source || meta.filename || meta.title || meta.id || m.id || `doc-${i}`;
      const score = (m.score || 0).toFixed(3);

      pineconeSourceIds.push(source);
      pineconeScores.push(parseFloat(score));

      return `[Source ${i + 1}: ${source} (score: ${score})]\n${text.substring(0, 800)}`;
    }).join('\n\n---\n\n');
  }
} catch (e) {
  pineconeContext = '';
}

// --- Extract Supabase metadata ---
let supabaseContext = '';
try {
  const supabaseData = $node['Query Supabase Metadata'].json;

  if (Array.isArray(supabaseData) && supabaseData.length > 0) {
    const tableList = supabaseData.map(t => `${t.table_name} (${t.column_count} columns)`).join(', ');
    supabaseContext = `Available Supabase tables: ${tableList}`;
  } else if (supabaseData && !supabaseData.error) {
    supabaseContext = `Supabase metadata available: ${JSON.stringify(supabaseData).substring(0, 500)}`;
  }
} catch (e) {
  supabaseContext = '';
}

// --- Build comprehensive project knowledge base (fallback) ---
const PROJECT_KB = `
## NOMOS AI PROJECT — KNOWLEDGE BASE

### Overview
Nomos AI is an advanced Multi-RAG Orchestrator system that answers complex questions by searching multiple databases simultaneously. It uses 4 specialized RAG pipelines and an intelligent orchestrator that automatically selects the best search method for each question.

### Target: Process 1M+ questions across 4 sectors (Construction/BTP, Industry, Finance, Legal) with 85%+ accuracy and <2.5s response time.

### The 4 RAG Pipelines
1. **Standard Pipeline** (text search): Question -> HyDE generation -> Pinecone vector search (10,411 vectors, 1024-dim Jina v3) -> Jina reranking -> Llama 70B answer. Phase 1: 85.5% accuracy.
2. **Graph Pipeline** (entity/relationship search): Question -> entity extraction -> Neo4j graph traversal (19,788 nodes, 76,717 relationships) -> LLM synthesis. Phase 1: 78.0% accuracy. Phase 2: 78.0% (500/500 COMPLETE).
3. **Quantitative Pipeline** (SQL/numbers): Question -> intent analysis -> SQL generation -> Supabase query (40+ tables, ~17,600 rows) -> LLM interpretation. Phase 1: 92.0% accuracy. Phase 2: 92.0% (500/500 COMPLETE). Best performing pipeline.
4. **Orchestrator Pipeline** (combines all 3): Question -> intent classification -> route to best pipeline(s) -> aggregate results. Phase 1: 80.0% accuracy.

### Phase 1 Results (200 questions) — PASSED Feb 20, 2026
- Standard: 85.5% | Graph: 78.0% | Quantitative: 92.0% | Orchestrator: 80.0% | Overall: 83.9%

### Phase 2 (1,000 questions per pipeline) — IN PROGRESS
- Graph: 78.0% (500/500 COMPLETE) | Quantitative: 92.0% (500/500 COMPLETE)
- Standard: ~36% (579/1000, paused) | Orchestrator: 0% (57/1000, being repaired)
- Total questions tested: 1,520+

### Infrastructure
- Control plane: Google Cloud VM (1 vCPU, 970MB RAM, Debian 11) running Claude Code Opus 4.6
- Execution: HuggingFace Space (16GB RAM, n8n v2.8.4 with queue mode, 12 workflows)
- Testing: GitHub Codespaces (2 cores, 8GB RAM, ephemeral)
- Websites: 4 Vercel deployments (ETI 4-sector site, PME Connectors, PME Use Cases, Dashboard)

### Databases
- Pinecone: sota-rag-jina-1024 (10,411 vectors, 1024-dim) + 2 secondary indexes
- Neo4j Aura: 19,788 nodes (8,531 people, 8,331 entities, 1,775 orgs, 840 cities), 76,717 relationships
- Supabase PostgreSQL: 40+ tables, ~17,600 rows (financials, balance sheets, sales, employees, benchmarks)

### Tech Stack
- LLMs: OpenRouter free tier — Llama 3.3 70B Instruct, Gemma 3 27B, Trinity Large
- Embeddings: Jina AI v3 (1024-dim, free 1M tokens/month)
- Reranking: Jina Reranker v2
- Workflow engine: n8n | Websites: Next.js 14/15 on Vercel
- 7 private GitHub repos | 7 MCP server connectors
- Budget: $0 (all services on free tiers)

### 4 Target Sectors
1. Construction/BTP: regulations, DTU standards, Eurocodes, safety, 7,600+ documents ready
2. Industry: predictive maintenance, quality control, supply chain
3. Finance: balance sheets, revenue analysis, financial ratios
4. Legal: contracts, compliance, GDPR, case law

### PME (Small Business) Features
- 15 multi-channel connectors: WhatsApp, Telegram, Slack, Teams, Discord, Gmail, Outlook, HubSpot, Salesforce, Pipedrive, Notion, Google Sheets, Airtable, Zendesk, Freshdesk
- 3 active PME workflows: Gateway, Slack Connector, Gmail Connector
- 200 documented use cases

### Project Phases
- Phase 1: 200q baseline — PASSED (83.9%)
- Phase 2: 1,000q/pipeline — IN PROGRESS
- Phase 3: ~10,000q — Next
- Phase 4: ~100,000q — Planned
- Phase 5: 1M+ — Final target

### Key Metrics
- 1,520+ questions tested | 83.9% Phase 1 accuracy | 22,070 vectors in Pinecone
- 19,788 Neo4j entities | ~17,600 Supabase rows | 7,609 sector documents
- 200+ commits | 55+ bugs resolved | 55 Claude Code sessions | 12 active workflows
`;

// --- Compute confidence based on retrieval quality ---
let confidence = 0.5; // baseline from KB
if (pineconeScores.length > 0) {
  const avgScore = pineconeScores.reduce((a, b) => a + b, 0) / pineconeScores.length;
  const topScore = Math.max(...pineconeScores);
  confidence = Math.min(0.95, 0.4 + (topScore * 0.4) + (avgScore * 0.2));
}
if (pineconeScores.length === 0 && !supabaseContext) {
  confidence = 0.5; // KB-only answer
}

// --- Build the combined context ---
let retrievalContext = '';
if (pineconeContext) {
  retrievalContext += `## Retrieved Documents from Vector Database\n\n${pineconeContext}\n\n`;
}
if (supabaseContext) {
  retrievalContext += `## Database Metadata\n\n${supabaseContext}\n\n`;
}

const fullContext = retrievalContext
  ? `${retrievalContext}\n\n## Project Knowledge Base (supplementary)\n\n${PROJECT_KB}`
  : PROJECT_KB;

// --- Build system prompt ---
const systemPrompt = lang === 'fr'
  ? `Tu es l'assistant IA officiel du projet Nomos AI Multi-RAG Orchestrator. Tu reponds aux questions sur le projet de maniere precise, professionnelle et structuree. Tu reponds TOUJOURS en francais.\n\nUtilise le contexte suivant pour repondre. Privilegie les documents recuperes (Retrieved Documents) quand ils sont pertinents, puis complete avec la base de connaissances projet.\n\nSi tu ne connais pas la reponse exacte, dis-le clairement. Ne fabrique JAMAIS de chiffres ou statistiques non mentionnes dans le contexte.\n\nStructure tes reponses avec des listes et tableaux quand c'est pertinent. Sois concis mais complet.\n\nCONTEXTE:\n${fullContext}`
  : `You are the official AI assistant for the Nomos AI Multi-RAG Orchestrator project. You answer questions about the project accurately, professionally, and with well-structured responses. You ALWAYS respond in English.\n\nUse the following context to answer. Prioritize Retrieved Documents when relevant, then supplement with the project knowledge base.\n\nIf you don't know the exact answer, say so clearly. NEVER fabricate numbers or statistics not mentioned in the context.\n\nStructure your responses with lists and tables when appropriate. Be concise but thorough.\n\nCONTEXT:\n${fullContext}`;

return {
  json: {
    question: question,
    lang: lang,
    detectedTopic: detectedTopic,
    systemPrompt: systemPrompt,
    confidence: Math.round(confidence * 100) / 100,
    sources: pineconeSourceIds,
    pinecone_matches: pineconeScores.length,
    has_supabase_data: !!supabaseContext
  }
};

// ============================================================
// Node 7: FORMAT FINAL RESPONSE
// Build the structured {answer, sources, confidence} response
// ============================================================

const llmOutput = $input.item.json;
const contextData = $node['Format Context'].json;

let answer = '';
let status = 'SUCCESS';
let model = 'llama-70b';
let tokensUsed = 0;

// --- Check for LLM errors ---
const hasError = llmOutput.error || llmOutput.code === 'ERR_GOT_REQUEST_ERROR' || (llmOutput.statusCode && llmOutput.statusCode >= 400);

try {
  if (hasError) {
    status = 'LLM_ERROR';
    const errMsg = llmOutput.error?.message || llmOutput.message || llmOutput.statusMessage || 'LLM service unavailable';
    answer = contextData.lang === 'fr'
      ? `Desole, le service LLM est temporairement indisponible (${errMsg}). Veuillez reessayer dans quelques instants.`
      : `Sorry, the LLM service is temporarily unavailable (${errMsg}). Please try again shortly.`;
  } else if (llmOutput.choices && llmOutput.choices.length > 0) {
    answer = (llmOutput.choices[0].message?.content || '').trim();
    model = llmOutput.model || model;
    if (llmOutput.usage) {
      tokensUsed = llmOutput.usage.total_tokens || 0;
    }
  } else if (llmOutput.error) {
    status = 'LLM_ERROR';
    const errMsg = llmOutput.error.message || JSON.stringify(llmOutput.error);
    answer = contextData.lang === 'fr'
      ? `Erreur du service LLM : ${errMsg}`
      : `LLM service error: ${errMsg}`;
  }
} catch (e) {
  status = 'PARSE_ERROR';
  answer = contextData.lang === 'fr'
    ? 'Erreur lors du traitement de la reponse. Veuillez reessayer.'
    : 'Error processing the response. Please try again.';
}

if (!answer || answer.length === 0) {
  status = 'EMPTY_RESPONSE';
  answer = contextData.lang === 'fr'
    ? 'Le modele n\'a pas genere de reponse. Veuillez reformuler votre question.'
    : 'The model did not generate a response. Please rephrase your question.';
}

// --- Adjust confidence based on LLM success ---
let finalConfidence = contextData.confidence || 0.5;
if (status !== 'SUCCESS') {
  finalConfidence = 0.1;
}

// --- Build sources array ---
const sources = (contextData.sources || []).map(s => (typeof s === 'string' ? s : String(s)));
if (contextData.has_supabase_data) {
  sources.push('supabase-metadata');
}

return {
  json: {
    answer: answer,
    sources: sources,
    confidence: finalConfidence,
    status: status,
    query: contextData.question,
    lang: contextData.lang,
    topic: contextData.detectedTopic,
    model: model,
    tokens_used: tokensUsed,
    pinecone_matches: contextData.pinecone_matches || 0,
    engine: 'PROJECT_CHATBOT_V3',
    version: '3.0',
    timestamp: new Date().toISOString()
  }
};
